{
  "items": [
    {
      "name": "sub_div",
      "module_name": "Mathlib.Algebra.Field.Basic",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : DivisionRing K] (a b c : K), (a - b) / c = a / c - b / c"
    },
    {
      "name": "tsub_div",
      "module_name": "Mathlib.Algebra.Order.Field.Canonical",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Semifield α] [inst_1 : LinearOrder α] [CanonicallyOrderedAdd α] [IsStrictOrderedRing α]\n  [inst_4 : Sub α] [OrderedSub α] (a b c : α), (a - b) / c = a / c - b / c"
    },
    {
      "name": "div_sub_div_same",
      "module_name": "Mathlib.Algebra.Field.Basic",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : DivisionRing K] (a b c : K), a / c - b / c = (a - b) / c"
    },
    {
      "name": "ofAdd_sub",
      "module_name": "Mathlib.Algebra.Group.TypeTags.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} [inst : Sub α] (x y : α), Multiplicative.ofAdd (x - y) = Multiplicative.ofAdd x / Multiplicative.ofAdd y"
    },
    {
      "name": "sub_self_div_two",
      "module_name": "Mathlib.Algebra.Order.Field.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : Field α] [inst_1 : PartialOrder α] [IsStrictOrderedRing α] (a : α), a - a / 2 = a / 2"
    },
    {
      "name": "Units.divp_sub_divp",
      "module_name": "Mathlib.Algebra.Ring.Units",
      "kind": "theorem",
      "type": "∀ {α : Type u} [inst : CommRing α] (a b : α) (u₁ u₂ : αˣ), a /ₚ u₁ - b /ₚ u₂ = (a * ↑u₂ - ↑u₁ * b) /ₚ (u₁ * u₂)"
    }
  ]
}
